import React, { useState } from "react";

export default function Navbar({ onLogin }) {
  const [menuOpen, setMenuOpen] = useState(false);
  const [loggedIn, setLoggedIn] = useState(false);

  const links = [
    { name: "Home", id: "homePage" },
    { name: "About Us", id: "About" },
    { name: "Contact", id: "contact" },
    { name: "Blog", id: "Blog" },
  ];

  // Handle login
  const handleLogin = () => {
    onLogin();       // call parent login function
    setLoggedIn(true); // switch navbar after login
    setMenuOpen(false);
  };

  return (
    <nav style={styles.navbar}>
      {/* Logo */}
      <a href="#homePage">
        {loggedIn ? (
          <div style={styles.logoLetter}>D</div> // First letter logo after login
        ) : (
          <img
            src="/Modern logo design f.png"
            alt="DailyCode Logo"
            style={styles.logoImg}
          />
        )}
      </a>

      {/* Links */}
      <ul
        style={{
          ...styles.navLinks,
          ...(menuOpen ? styles.showMenu : {}),
        }}
      >
        {links.map((link, i) => (
          <li key={i}>
            <a href={`#${link.id}`} style={styles.link}>
              {link.name}
            </a>
          </li>
        ))}

        {!loggedIn && (
          <li>
            <a
              href="#login"
              style={styles.link}
              onClick={(e) => {
                e.preventDefault();
                handleLogin();
              }}
            >
              Log in
            </a>
          </li>
        )}
      </ul>

      {/* Hamburger Button */}
      <button
        style={styles.menuBtn}
        onClick={() => setMenuOpen(!menuOpen)}
      >
        {menuOpen ? "✖" : "☰"}
      </button>
    </nav>
  );
}

const styles = {
  navbar: {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    background: "rgba(17, 24, 39, 0.8)",
    backdropFilter: "blur(10px)",
    color: "white",
    height: "70px",
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    padding: "0 2rem",
    zIndex: 1000,
    boxShadow: "0 4px 20px rgba(0,0,0,0.3)",
  },

  logoImg: {
    width: "140px",
    height: "auto",
    objectFit: "contain",
    cursor: "pointer",
    transition: "transform 0.3s ease",
  },

  logoLetter: {
    fontSize: "2rem",
    fontWeight: "bold",
    color: "white",
    cursor: "pointer",
  },

  navLinks: {
    listStyle: "none",
    display: "flex",
    gap: "2rem",
  },

  link: {
    color: "white",
    fontSize: "1.1rem",
    textDecoration: "none",
    transition: "color 0.3s ease",
    cursor: "pointer",
  },

  menuBtn: {
    display: "none",
    fontSize: "2rem",
    background: "none",
    border: "none",
    color: "white",
    cursor: "pointer",
    zIndex: 1001,
  },

  showMenu: {
    position: "absolute",
    top: "70px",
    left: 0,
    width: "100%",
    background: "rgba(17, 24, 39, 0.95)",
    backdropFilter: "blur(8px)",
    padding: "1rem",
    listStyle: "none",
    display: "flex",
    flexDirection: "column",
    gap: "1rem",
    animation: "slideDown 0.3s ease",
  },
};

// Inject responsive styles dynamically
const mediaQuery = `
  @media (max-width: 768px) {
    ul {
      display: none !important;
    }
    button {
      display: block !important;
    }
  }
`;

const styleSheet = document.styleSheets[0];
styleSheet.insertRule(mediaQuery, styleSheet.cssRules.length);
